// 平台页与原生登录引导的文案。key 只在这里定义一次：Web 的消息表把它并入自己的表
// （同一个 key 不在两处各写一份），Desktop 直接用这里的翻译。
//
// 契约枚举（reason code、审批状态、决定、审批选择器）的文案按枚举穷举：契约新增一个
// 值时这里编译不过，逼着给出说明，而不是让新值悄悄落进一个笼统的「出错了」。code
// 本身是稳定标识，界面同时显示文案与 code（apps/06 §4）。

