  "componentActions.title": { en: "Run a component action", "zh-CN": "执行组件动作" },
  "componentActions.boundary": { en: "Use a registered action and a frozen native content reference. Supply actionKey, target ID/version, optional workspaceId, and componentAction (actionVersion, inputReference, existing resultExposurePolicyId/version). Never paste SQL, credentials or result bodies. Core checks your current permission, approval and quota; native pages retain their own sessions.", "zh-CN": "使用已登记动作及冻结的原生内容引用。填写 actionKey、目标 ID/版本、可选 workspaceId，以及 componentAction（actionVersion、inputReference、已存在的 resultExposurePolicyId/version）。不要粘贴 SQL、凭据或结果正文。Core 重核本人当前权限、审批和额度；原生页面仍使用自己的会话。" },
  "componentActions.document": { en: "Component action references (JSON)", "zh-CN": "组件动作引用（JSON）" },
