  "componentActions.prepare": { en: "Review action", "zh-CN": "核对动作" },
  "componentActions.review": { en: "Confirm this frozen action. An uncertain outcome can only reconcile this same intent.", "zh-CN": "确认此次冻结动作。结果不明时只能查证同一请求，不重新执行。" },
