  "bindings.documentHelp": { en: "Supply the ApplicationBindingCreate document for an approved release and registered adapter. Keep secretRefs empty and never put passwords or access tokens in the document; enter the release's declared credentials in the separate fields below.", "zh-CN": "提交已批准发行版本与已登记 Adapter 的 ApplicationBindingCreate 配置。secretRefs 保持为空，配置中不要填写密码或访问令牌；发行版本声明的凭据在下方单独字段中填写。" },
  "bindings.releases": { en: "Approved releases available for connection", "zh-CN": "可接入的已批准发行版本" },
