  "bindings.secretsHelp": { en: "Each value is written once to this organization's secret store by the same governed request and is never shown again. Only its versioned reference is recorded.", "zh-CN": "各项值由同一受治理请求一次写入本组织的密钥存储，之后不再显示；只记录其版本化引用。" },
  "bindings.secretsMissing": { en: "Enter every secret declared by an approved release listed above before reviewing the connection.", "zh-CN": "请先为上方所列已批准发行版本声明的每项凭据填写值，再预览接入。" },
