  "bindings.createWarning": { en: "Create this connection in the selected scope. It becomes usable only when the actual adapter and governance projections are ready; submitting is not connection success.", "zh-CN": "在所选作用域建立此连接。Adapter 与治理投影实际就绪后才可使用；提交不表示接入成功。" },
  "bindings.disableWarning": { en: "Stop new Kailo calls and reconcile in-flight operations. This does not stop the external service or delete its data.", "zh-CN": "停止新的 Kailo 调用并对账在途操作；不会关闭外部服务或删除其数据。" },
