  "components.documentHelp": { en: "Provide the complete immutable documents. The deployed isolated candidate must match the artifact digest. Credentials, endpoints and passing reports are not accepted here.", "zh-CN": "提交完整且不可变的清单。已部署的隔离候选必须匹配制品摘要；此处不接收凭据、执行端点或自报通过报告。" },
