  "components.registerWarning": { en: "Confirm these exact documents and start the isolated suite. Registration is recorded only after every required check has native evidence; submitting a task is not registration success.", "zh-CN": "确认这些原始清单并启动隔离套件。全部必需检查取得原生证据后才会登记；任务提交不表示登记成功。" },
