  "components.approveWarning": { en: "Request Catalog approval for this exact release. The registrar and requester cannot approve it. Approval also requires the current deployed platform capabilities; no business binding will be activated.", "zh-CN": "为这个确切版本申请 Catalog 批准。登记人和申请人不能审批；批准还必须通过当前部署能力兼容核验，不会启用业务 binding。" },
