  "skills.createBoundary": { en: "Creates a Tenant-level Skill definition owned by you. It has no versions until you upload one, and creating it grants nothing to any agent.", "zh-CN": "创建由你负责的 Tenant 级 Skill 定义。上传版本前没有内容，创建本身不授予任何 Agent 权限。" },
