  "skills.slugHint": { en: "Lowercase letters, digits and hyphens, at most 64 characters. It must equal the name in SKILL.md and is what members type as $name.", "zh-CN": "小写字母、数字与连字符，至多 64 个字符；须与 SKILL.md 中的 name 一致，成员以 $名称 引用。" },
  "skills.slugInvalid": { en: "Use lowercase letters, digits and hyphens, starting and ending with a letter or digit.", "zh-CN": "只能使用小写字母、数字与连字符，且以字母或数字开头和结尾。" },
  "skills.previewCreate": { en: "Create skill {name} (${slug}).", "zh-CN": "创建 Skill {name}（${slug}）。" },
  "skills.boundary": { en: "Versions are immutable once uploaded; publishing makes a version selectable by agent versions. Disabling is irreversible and stops the skill in running installations before their next turn.", "zh-CN": "版本上传后不可修改；发布后才能被 Agent 版本选用。停用不可撤销，运行中的安装会在下一回合前停用该 Skill。" },
