  "skills.unshare": { en: "Stop sharing", "zh-CN": "取消分享" },
  "skills.disable": { en: "Disable skill", "zh-CN": "停用 Skill" },
  "skills.reviewShare": { en: "Share {name} with every member of this Tenant: they can discover it, read published versions and reference them. Sharing grants no edit or management rights.", "zh-CN": "将 {name} 分享给本 Tenant 全体成员：成员可发现、读取已发布版本并引用；分享不授予编辑或管理权限。" },
  "skills.reviewUnshare": { en: "Stop sharing {name}. Agent versions that already reference it keep their reference; installations whose owner can no longer read it stop using it before their next turn.", "zh-CN": "取消分享 {name}。已引用它的 Agent 版本保留引用；安装负责人不再可读时，该安装会在下一回合前停用它。" },
  "skills.reviewDisable": { en: "Disable {name}. This cannot be undone: no new references are accepted and running installations stop using it before their next turn. Versions and history are kept.", "zh-CN": "停用 {name}。此操作不可撤销：不再接受新引用，运行中的安装会在下一回合前停用它；版本与历史保留。" },
  "skills.reviewPublish": { en: "Publish version {version} of {name}. Agent versions can then reference it.", "zh-CN": "发布 {name} 的版本 {version}，之后 Agent 版本即可引用。" },
  "skills.reviewRetire": { en: "Retire version {version} of {name}. New references are refused; published agent versions and installations that already use it are unchanged.", "zh-CN": "退役 {name} 的版本 {version}。不再接受新引用；已引用它的已发布 Agent 版本与安装不受影响。" },
