  "skills.uploadBoundary": { en: "Upload a SKILL.md, a .tar or .tar.gz, or choose a folder. The package must contain exactly one SKILL.md whose name is {slug}; the agent runtime cannot read or run other files, so any other file, executable bit or link is rejected.", "zh-CN": "上传 SKILL.md、.tar 或 .tar.gz，或选择一个文件夹。包内须恰有一个 SKILL.md 且 name 为 {slug}；Agent 运行时无法读取或执行其他文件，因此其他文件、可执行位或链接都会被拒绝。" },
  "skills.chooseFile": { en: "SKILL.md or archive", "zh-CN": "SKILL.md 或归档" },
