  "skills.requirementsHint": { en: "contract_key@version, separated by commas. They must also be requested by every agent version that uses this skill and grant no tool access.", "zh-CN": "以逗号分隔的 contract_key@version；引用此 Skill 的 Agent 版本也须声明这些需求，它们不授予任何工具权限。" },
