  "skills.version.selectHint": { en: "Published versions of skills you can read. At most 16, one version per skill; references grant no permissions.", "zh-CN": "你可读的 Skill 的已发布版本。至多 16 个，每个 Skill 一个版本；引用不授予任何权限。" },
